  // Phase-accumulator (DDS) chirp generator -- phase_step ramps linearly
  // each cycle so instantaneous frequency sweeps from ~5MHz to ~45MHz
  // across the run, through the filter's ~20-31MHz passband. Constants
  // must match generate_coeffs.py / filter_params.json.
  reg  [31:0] phase_acc;
  reg  [31:0] phase_step;
  localparam PHASE_STEP0    = 32'd214748365; // ~5 MHz at 100MHz clk
  localparam PHASE_STEP_INC = 32'd343597;    // per-cycle ramp -> ~45MHz by CHIRP_LEN
  localparam CHIRP_LEN      = 32'd5000;
  localparam LATENCY_MARGIN = 32'd300;
  localparam SETTLE_CYCLES  = 32'd10;

  integer cycle;
  integer outfile;

  initial begin
    sclr       = 1;
    din        = 0;
    phase_acc  = 0;
    phase_step = PHASE_STEP0;
    cycle      = 0;

    outfile = $fopen("results.csv", "w");
    $fdisplay(outfile, "cycle,din,dout,rfd,rdy");

    repeat (SETTLE_CYCLES) @(posedge clk);
    sclr = 0;

    while (cycle < CHIRP_LEN + LATENCY_MARGIN) begin
      @(posedge clk);
      #1; // let the core's clocked outputs settle before sampling
      $fdisplay(outfile, "%0d,%0d,%0d,%0d,%0d", cycle, din, dout, rfd, rdy);

      if (cycle < CHIRP_LEN) begin
        din        = sine_lut[phase_acc[31:24]];
        phase_acc  = phase_acc + phase_step;
        phase_step = phase_step + PHASE_STEP_INC;
      end else begin
        din = 0;
      end
      cycle = cycle + 1;
    end

    $fclose(outfile);
    $display("poc_bpf_tb: simulation complete, %0d cycles", cycle);
    $finish;
  end

endmodule
